import numpy as np

# MECHANISM: Use a piecewise function to balance between tight fit and spreading items.

def priority(item, bins):
    max_capacity = 150
    remaining_capacity = bins - item
    thresholds = np.array([50, 100, 150])
    scores = np.zeros_like(bins)

    for i in range(len(thresholds)):
        mask = remaining_capacity <= thresholds[i]
        if i == 0:
            scores[mask] = thresholds[i] - remaining_capacity[mask]  # Linear decay
        elif i == 1:
            scores[mask] = (thresholds[i] - remaining_capacity[mask]) * 0.5  # Half decay
        else:
            scores[mask] = 0  # No preference for remaining capacity >= 150

    return scores

