# MECHANISM: Use a combination of linear and logarithmic functions to balance between tight fit and spreading items.

def priority(item, bins):
    max_capacity = 150
    remaining_capacity = bins - item
    thresholds = np.array([50, 100, 150])
    scores = np.zeros_like(bins)

    for i in range(len(thresholds)):
